import { describe, expect, it } from "vitest";

import { buildReviewPlan, matchesGlob, renderSummaryBody, type PullFileEntry } from "../src/index";

const PATCH = [
  "diff --git a/src/app.ts b/src/app.ts",
  "--- a/src/app.ts",
  "+++ b/src/app.ts",
  "@@ -1,2 +1,2 @@",
  " line1",
  "-old2",
  "+new2",
].join("\n");

const GENERATED_PATCH = [
  "diff --git a/src/api.ts b/src/api.ts",
  "--- a/src/api.ts",
  "+++ b/src/api.ts",
  "@@ -0,0 +1,3 @@",
  "+// Code generated by protoc. DO NOT EDIT.",
  "+// @generated",
  "+export const x = 1;",
].join("\n");

function entry(overrides: Partial<PullFileEntry> = {}): PullFileEntry {
  return {
    sha: "abc123",
    filename: "src/app.ts",
    status: "modified",
    additions: 1,
    deletions: 1,
    changes: 2,
    patch: PATCH,
    ...overrides,
  };
}

describe("matchesGlob", () => {
  it("matches * within one segment only", () => {
    expect(matchesGlob("*.snap", "snap.snap")).toBe(true);
    expect(matchesGlob("*.snap", "src/snap.snap")).toBe(true);
    expect(matchesGlob("src/*.ts", "src/app.ts")).toBe(true);
    expect(matchesGlob("src/*.ts", "src/nested/app.ts")).toBe(false);
  });

  it("matches ** across segments", () => {
    expect(matchesGlob("docs/**", "docs/guide.md")).toBe(true);
    expect(matchesGlob("docs/**", "docs/a/b/guide.md")).toBe(true);
    expect(matchesGlob("docs/**", "src/docs/guide.md")).toBe(false);
    expect(matchesGlob("**/*.generated.ts", "src/foo.generated.ts")).toBe(true);
    expect(matchesGlob("**/*.generated.ts", "foo.generated.ts")).toBe(true);
    expect(matchesGlob("**/migrations/**", "db/migrations/0042.sql")).toBe(true);
  });

  it("matches exact and question-sensitive literals", () => {
    expect(matchesGlob("pnpm-lock.yaml", "pnpm-lock.yaml")).toBe(true);
    expect(matchesGlob("pnpm-lock.yaml", "src/pnpm-lock.yaml")).toBe(true);
    expect(matchesGlob("pnpm-lock.yaml", "pnpm-lock.yaml.bak")).toBe(false);
    expect(matchesGlob("src/app.ts", "src/app.ts")).toBe(true);
    expect(matchesGlob("src/app.ts", "src/app.tsx")).toBe(false);
    expect(matchesGlob("", "src/app.ts")).toBe(false);
  });
});

describe("buildReviewPlan default ignores", () => {
  it.each([
    ["pnpm-lock.yaml", "lockfile"],
    ["package-lock.json", "lockfile"],
    ["yarn.lock", "lockfile"],
    ["bun.lock", "lockfile"],
    ["Cargo.lock", "lockfile"],
    ["go.sum", "lockfile"],
    ["poetry.lock", "lockfile"],
    ["Gemfile.lock", "lockfile"],
    ["backend/requirements.lock", "lockfile"],
    ["dist/bundle.js", "dist/"],
    ["build/output.js", "build/"],
    ["vendor/lib/helper.go", "vendor/"],
    ["src/app.min.js", "minified"],
    ["src/app.min.css", "minified"],
    ["src/__snapshots__/app.test.ts.snap", "snapshot"],
  ])("skips %s as %s", (filename, category) => {
    const plan = buildReviewPlan([entry({ filename })]);
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.skippedFiles).toHaveLength(1);
    expect(plan.skippedFiles[0]!.path).toBe(filename);
    expect(plan.skippedFiles[0]!.reason).toContain(category);
  });

  it("skips files matching default-generated example patterns via user ignore", () => {
    const plan = buildReviewPlan([entry({ filename: "src/foo.generated.ts" })], {
      ignore: ["**/*.generated.ts"],
    });
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.skippedFiles[0]!.reason).toBe("user ignore: **/*.generated.ts");
  });

  it("skips files whose patch contains an @generated marker", () => {
    const generated = entry({ filename: "src/api.ts", patch: GENERATED_PATCH });
    const plan = buildReviewPlan([generated]);
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.skippedFiles).toEqual([{ path: "src/api.ts", reason: "generated" }]);
  });

  it("skips binary files with no patch", () => {
    const plan = buildReviewPlan([
      entry({ filename: "assets/logo.png", status: "added", patch: undefined }),
    ]);
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.skippedFiles).toEqual([{ path: "assets/logo.png", reason: "binary" }]);
  });

  it("reviews truncated patches that still carry a patch", () => {
    const plan = buildReviewPlan([entry({ filename: "src/big.ts" })]);
    expect(plan.reviewFiles).toHaveLength(1);
    expect(plan.partial).toBe(false);
  });
});

describe("buildReviewPlan user ignore and include", () => {
  it("applies user ignore globs with the glob in the reason", () => {
    const plan = buildReviewPlan(
      [entry({ filename: "docs/guide.md" }), entry({ filename: "src/app.ts" })],
      { ignore: ["docs/**"] },
    );
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["src/app.ts"]);
    expect(plan.skippedFiles).toEqual([{ path: "docs/guide.md", reason: "user ignore: docs/**" }]);
  });

  it("treats include globs as an allowlist", () => {
    const plan = buildReviewPlan(
      [entry({ filename: "src/app.ts" }), entry({ filename: "docs/guide.md" })],
      { include: ["src/**"] },
    );
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["src/app.ts"]);
    expect(plan.skippedFiles).toEqual([{ path: "docs/guide.md", reason: "not in include list" }]);
  });

  it("default ignores win over the include allowlist", () => {
    const plan = buildReviewPlan([entry({ filename: "dist/bundle.js" })], {
      include: ["dist/**"],
    });
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.skippedFiles[0]!.reason).toContain("dist/");
  });
});

describe("buildReviewPlan size limits", () => {
  function sizedFiles(count: number): PullFileEntry[] {
    return Array.from({ length: count }, (_, i) =>
      entry({ filename: `src/file${i}.ts`, additions: 1, deletions: 0, changes: 1 }),
    );
  }

  it("caps at max_files and reports the rest as over max_files", () => {
    const plan = buildReviewPlan(sizedFiles(60));
    expect(plan.reviewFiles).toHaveLength(50);
    expect(plan.notReviewed).toHaveLength(10);
    expect(plan.notReviewed.every((file) => file.reason === "over max_files")).toBe(true);
    expect(plan.partial).toBe(true);
    expect(plan.totalDiffLines).toBe(50);
  });

  it("reviews a 200-file fixture under caps with max_files raised", () => {
    const files = Array.from({ length: 200 }, (_, i) =>
      entry({
        filename: `src/file${String(i).padStart(3, "0")}.ts`,
        additions: 10,
        deletions: 5,
        changes: 15,
      }),
    );
    const plan = buildReviewPlan(files, { maxFiles: 200, maxDiffLines: 3000 });
    expect(plan.reviewFiles).toHaveLength(200);
    expect(plan.notReviewed).toHaveLength(0);
    expect(plan.partial).toBe(false);
    expect(plan.totalDiffLines).toBe(3000);
  });

  it("caps at max_diff_lines and reports the rest as over max_diff_lines", () => {
    const files = [
      entry({ filename: "src/big.ts", additions: 2000, deletions: 500, changes: 2500 }),
      entry({ filename: "src/small.ts", additions: 400, deletions: 100, changes: 500 }),
      entry({ filename: "src/extra.ts", additions: 300, deletions: 100, changes: 400 }),
    ];
    const plan = buildReviewPlan(files);
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["src/big.ts", "src/small.ts"]);
    expect(plan.notReviewed).toEqual([{ path: "src/extra.ts", reason: "over max_diff_lines" }]);
    expect(plan.totalDiffLines).toBe(3000);
    expect(plan.partial).toBe(true);
  });

  it("a file larger than the whole budget still leaves notReviewed non-empty", () => {
    const plan = buildReviewPlan([
      entry({ filename: "src/huge.ts", additions: 5000, deletions: 0, changes: 5000 }),
    ]);
    expect(plan.reviewFiles).toHaveLength(0);
    expect(plan.notReviewed).toEqual([{ path: "src/huge.ts", reason: "over max_diff_lines" }]);
    expect(plan.partial).toBe(true);
  });

  it("honours custom caps from options", () => {
    const plan = buildReviewPlan(sizedFiles(5), { maxFiles: 2, maxDiffLines: 100 });
    expect(plan.reviewFiles).toHaveLength(2);
    expect(plan.notReviewed).toHaveLength(3);
    expect(plan.notReviewed.every((file) => file.reason === "over max_files")).toBe(true);
  });
});

describe("buildReviewPlan priority ordering", () => {
  it("ranks source files before tests", () => {
    const plan = buildReviewPlan(
      [
        entry({ filename: "src/app.test.ts", additions: 5, deletions: 5, changes: 10 }),
        entry({ filename: "src/app.ts", additions: 1, deletions: 0, changes: 1 }),
      ],
      { maxFiles: 1, maxDiffLines: 1000 },
    );
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["src/app.ts"]);
    expect(plan.notReviewed).toEqual([{ path: "src/app.test.ts", reason: "over max_files" }]);
  });

  it("ranks larger changes first within source files", () => {
    const plan = buildReviewPlan(
      [
        entry({ filename: "src/small.ts", additions: 1, deletions: 0, changes: 1 }),
        entry({ filename: "src/big.ts", additions: 50, deletions: 10, changes: 60 }),
        entry({ filename: "src/mid.ts", additions: 10, deletions: 5, changes: 15 }),
      ],
      { maxFiles: 2, maxDiffLines: 1000 },
    );
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["src/big.ts", "src/mid.ts"]);
    expect(plan.notReviewed).toEqual([{ path: "src/small.ts", reason: "over max_files" }]);
  });

  it("ranks larger tests before smaller tests once sources are kept", () => {
    const plan = buildReviewPlan(
      [
        entry({ filename: "__tests__/small.test.ts", additions: 1, deletions: 0, changes: 1 }),
        entry({ filename: "spec/big.spec.ts", additions: 20, deletions: 0, changes: 20 }),
      ],
      { maxFiles: 1, maxDiffLines: 1000 },
    );
    expect(plan.reviewFiles.map((file) => file.filename)).toEqual(["spec/big.spec.ts"]);
  });
});

describe("buildReviewPlan flags and summary wiring", () => {
  it("sets partial to false when everything is reviewed", () => {
    const plan = buildReviewPlan([entry()]);
    expect(plan.partial).toBe(false);
    expect(plan.notReviewed).toEqual([]);
    expect(plan.totalDiffLines).toBe(2);
  });

  it("renders the notReviewed list in the summary", () => {
    const body = renderSummaryBody({
      files: [{ path: "src/app.ts", status: "modified" }],
      skipped: [{ path: "pnpm-lock.yaml", reason: "ignored by default: lockfile" }],
      notReviewed: [{ path: "src/extra.ts", reason: "over max_files" }],
    });
    expect(body).toContain("Not reviewed");
    expect(body).toContain("`src/extra.ts` — over max_files");
    expect(body).toContain("`pnpm-lock.yaml` — ignored by default: lockfile");
  });
});
